// Strategy data types
export type AssetClassId =
  | "options"
  | "stocks"
  | "etfs"
  | "fixed-income"
  | "indexes"
  | "volatility"
  | "fx"
  | "commodities"
  | "futures"
  | "structured"
  | "convertibles"
  | "tax-arb"
  | "misc"
  | "distressed"
  | "real-estate"
  | "cash"
  | "crypto"
  | "global-macro"
  | "infrastructure";

export type StrategyType =
  | "directional"
  | "arbitrage"
  | "relative-value"
  | "hedging"
  | "machine-learning"
  | "event-driven"
  | "income";

export type MarketView =
  | "bullish"
  | "bearish"
  | "neutral"
  | "volatile"
  | "low-vol"
  | "multi";

export interface AssetClass {
  id: AssetClassId;
  chapter: number;
  name: string;
  tagline: string;
  icon: string; // lucide icon name
  accent: string; // tailwind color token
  count: number; // computed
}

export interface Strategy {
  id: string;
  number: string;
  name: string;
  category: AssetClassId;
  type: StrategyType;
  marketView: MarketView;
  riskLevel: 1 | 2 | 3 | 4 | 5;
  complexity: 1 | 2 | 3 | 4 | 5;
  shortDesc: string;
  description: string;
  keyConcepts: string[];
  formula?: string;
  methodology?: string;
  instruments: string[];
  maxProfit?: string;
  maxLoss?: string;
  example?: string;
  featured?: boolean;
}

